balance = -5
try:
    assert balance >= 0, 'balance invariant failed'
except AssertionError as error:
    print(str(error))

def parse_age(raw):
    age = int(raw)
    if age < 0:
        raise ValueError('age cannot be negative')
    return age
try:
    parse_age('-1')
except ValueError as error:
    print(str(error))

